import fs from 'node:fs/promises';const dir='artifacts/realtor-batch-20261016';const m=JSON.parse(await fs.readFile(dir+'/prepared-manifest.json'));const backlog=JSON.parse(await fs.readFile(dir+'/candidate-backlog.json'));const cache=JSON.parse(await fs.readFile(dir+'/lookup-cache.json'));for(const line of (await fs.readFile(dir+'/new-lookups.jsonl','utf8')).trim().split('\n')){const r=JSON.parse(line);cache[r.result.data.phone_number]=r;}const rows=[...m.primary,...m.reserve,...backlog].filter(c=>{const r=cache[c.phone],d=r?.result?.data;return d?.country_code==='CA'&&d?.valid_number===true&&d?.carrier?.type==='mobile'&&!d.carrier.error_code&&Date.parse(r.at)>Date.now()-14*86400000}).slice(0,1700).map(c=>({...c,lookup_at:cache[c.phone].at,carrier_status:'verified_mobile'}));await fs.writeFile(dir+'/carrier-verification.json',JSON.stringify({at:new Date().toISOString(),campaign:m.campaign,target_confirmed_delivered:1500,primary:rows.slice(0,1500),reserve:rows.slice(1500),carrier_verified:rows.length,incremental:true}));console.log('Verified candidates ready:',rows.length);
